  build_row(mlo, "nbheur2",    "Hours worked at $t^D-2$",           digits = 2),
  build_row(mlo, "nbheur3",    "Hours worked at $t^D-3$",           digits = 2),
  build_row(mlo, "nbsa_ent1",  "\\# employees at firm at $t^D-1$",  digits = 1)
)

tex <- c(
  "% Generated by main_tables_2026-04_descriptives_mlo.R",
  "% Source: matching_balance.csv from CASD export Export_20260331,",
  "% sample = panelpanSIZE2 (MLO30: firms with empclos >= 10 in t-1 and",
  "% Picart-corrected employment loss between t-1 and t).",
  "% This file replaces the stale MLOAllmatchvar_20210908.tex.",
  "{",
  "\\def\\sym#1{\\ifmmode^{#1}\\else\\(^{#1}\\)\\fi}",
  "\\begin{tabular}{l*{3}{c}}",
  "\\hline\\hline",
  "            & \\multicolumn{1}{c}{(1)} & \\multicolumn{1}{c}{(2)} & \\multicolumn{1}{c}{(3)} \\\\",
  "            & \\multicolumn{1}{c}{MLO30} & \\multicolumn{1}{c}{Control} & \\multicolumn{1}{c}{Norm.\\ Diff.} \\\\",
  "\\hline",
  rows,
  "\\hline",
  sprintf("Obs (workers)              & %s & %s & %s \\\\",
