# Pull annual gross earnings (sbr) at d=-2 from S2 event-studies
# (S2 is correct here: worker-level outcome, treatment_path == TRUE)
es_path <- "/Users/clementmalgouyres/Library/CloudStorage/Dropbox/Layoff/00_ExportsCASD/Export_20260423/event_studies-main_samples/panelpanSIZE2-res.csv"
es <- read_csv(es_path, show_col_types = FALSE)
sbr_dm2 <- es |>
  filter(treatment_path,
         interaction_group == "none",
         is.na(description),
         dep_var == "sbr",
         distance == -2) |>
  slice(1)

# Helper for the quantivar table -- handles missing SD gracefully
build_row_q <- function(df, var_root, label, digits = 2,
                        treated_mean = NULL, control_mean = NULL,
                        nd = NULL, treated_sd = NULL, control_sd = NULL) {
  # If explicit means are passed, use them; otherwise look up in df.
  if (is.null(treated_mean)) {
    mn <- df |> filter(name == var_root) |> slice(1)
    treated_mean <- mn$Treated
    control_mean <- mn$Control
    nd           <- mn$`Norm. Diff.`
  }
  if (is.null(treated_sd)) {
    sd_row <- df |> filter(name == paste0(var_root, "_sd")) |> slice(1)
    treated_sd <- if (nrow(sd_row) > 0) sd_row$Treated else NA_real_
    control_sd <- if (nrow(sd_row) > 0) sd_row$Control else NA_real_
  }

  fmt_sd_or_dash <- function(x) if (is.na(x)) "--" else fmt_sd(x, digits)

  c(
    sprintf("%-50s & %s & %s & %s \\\\",
            label,
            fmt_num(treated_mean, digits),
            fmt_num(control_mean, digits),
            if (is.na(nd)) "--" else fmt_nd(nd)),
    sprintf("%-50s & %s & %s & %s \\\\",
            "",
            fmt_sd_or_dash(treated_sd),
            fmt_sd_or_dash(control_sd),
            "")
  )
}

# Annual gross earnings (sbr): we have mean from event-study CSV but not SD
# (matching_balance.csv does not export sbr; event-study CSV has only means).
# Compute Imbens-Rubin norm. diff. is impossible without SDs, so report --.
sbr_treated_mean <- sbr_dm2$mean_treated
sbr_control_mean <- sbr_dm2$mean_control

rows_q <- c(
  build_row_q(mlo, "sx",                       "Gender: Male",                                      digits = 2),
  build_row_q(mlo, "sbr_at_dm2",               "Annual gross earnings at $t^D-2$",                  digits = 2,
              treated_mean = sbr_treated_mean,
              control_mean = sbr_control_mean,
